package com.tarapickle.identity.api; import com.tarapickle.identity.api.IdentityDtos.*; import com.tarapickle.identity.application.AccountService; import io.swagger.v3.oas.annotations.*; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import io.swagger.v3.oas.annotations.tags.Tag; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/account/sessions") @RequiredArgsConstructor @Tag(name="Sessions") @SecurityRequirement(name="bearerAuth") public class SessionController {private final AccountService service; @GetMapping @Operation(operationId="listSessions",summary="List sessions") public List<SessionResponse> list(@AuthenticationPrincipal Jwt j){return service.list(AuthenticationController.uid(j),AuthenticationController.sid(j));} @DeleteMapping("/{sessionId}") @ResponseStatus(HttpStatus.NO_CONTENT) @Operation(operationId="revokeSession",summary="Revoke a session") public void one(@AuthenticationPrincipal Jwt j,@PathVariable UUID sessionId){service.revoke(AuthenticationController.uid(j),sessionId);} @DeleteMapping @ResponseStatus(HttpStatus.NO_CONTENT) @Operation(operationId="revokeAllSessions",summary="Revoke every session") public void all(@AuthenticationPrincipal Jwt j){service.revokeAll(AuthenticationController.uid(j));}}
